// The launcher icon: the robot on black as an adaptive icon (foreground in the safe zone, black background,
// monochrome layer for themed icons), legacy PNGs for every density, and the 512px Play listing icon.
// Generated by scripts/make-launcher-icon.py from the iOS app icon.
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";

const RES = "app/src/main/res";
const DENSITIES = { mdpi: 1, hdpi: 1.5, xhdpi: 2, xxhdpi: 3, xxxhdpi: 4 };

// Width, height and colour type from a PNG's IHDR chunk.
function png(path) {
  const b = readFileSync(path);
  assert.equal(b.toString("latin1", 1, 4), "PNG", `${path} is not a PNG`);
  return { width: b.readUInt32BE(16), height: b.readUInt32BE(20), colorType: b[25] };
}

test("the manifest uses @mipmap/ic_launcher", () => {
  assert.match(readFileSync("app/src/main/AndroidManifest.xml", "utf8"), /android:icon="@mipmap\/ic_launcher"/);
});

test("the adaptive icon has a black background, the robot foreground and a monochrome layer", () => {
  const xml = readFileSync(`${RES}/mipmap-anydpi/ic_launcher.xml`, "utf8");
  assert.match(xml, /<adaptive-icon/);
  assert.match(xml, /<background android:drawable="@color\/ic_launcher_background"/);
  assert.match(xml, /<foreground android:drawable="@drawable\/ic_launcher_foreground"/);
  assert.match(xml, /<monochrome android:drawable="@drawable\/ic_launcher_monochrome"/);
  assert.match(readFileSync(`${RES}/values/colors.xml`, "utf8"), /name="ic_launcher_background">#FF000000</);
});

test("foreground and monochrome layers exist for every density at 108dp, with transparency", () => {
  for (const [density, factor] of Object.entries(DENSITIES)) {
    for (const layer of ["ic_launcher_foreground", "ic_launcher_monochrome"]) {
      const path = `${RES}/drawable-${density}/${layer}.png`;
      assert.ok(existsSync(path), `${path} is missing`);
      const { width, height, colorType } = png(path);
      assert.deepEqual([width, height], [108 * factor, 108 * factor], path);
      assert.equal(colorType, 6, `${path} must be RGBA`);
    }
  }
});

test("legacy launcher PNGs exist for every density at 48dp", () => {
  for (const [density, factor] of Object.entries(DENSITIES)) {
    const { width, height } = png(`${RES}/mipmap-${density}/ic_launcher.png`);
    assert.deepEqual([width, height], [48 * factor, 48 * factor], density);
  }
});

test("the Play listing icon is a 512x512 PNG", () => {
  const { width, height } = png("store/icon-512.png");
  assert.deepEqual([width, height], [512, 512]);
});

test("the placeholder vector icon is gone", () => {
  assert.equal(existsSync(`${RES}/drawable/ic_launcher_foreground.xml`), false);
});
